"""Triton implementation of ``aten::_foreach_sqrt_`` for Ascend 910B.

Semantics: for every tensor in the list, apply sqrt element-wise *in place*,
preserving storage, stride, dtype and shape, and return ``None``.

Rules reproduced from ATen:
  * non floating / non complex inputs raise RuntimeError (result type Float
    can't be cast to the desired output type ...)
  * complex32 raises, complex64/128 are supported
  * stride-0 (expanded) inputs raise (more than one element refers to a
    single memory location)
  * an empty tensor list raises RuntimeError
  * half dtypes are computed in fp32 opmath and rounded once on store

Launch architecture: consecutive dense tensors that share a dtype are fused
into ONE Triton launch (up to ``_MAX_TENSORS`` per launch) so that a long
tensor list does not pay one dispatch per element of the list.  The fused
kernel receives the tensor base pointers directly as kernel arguments: a
device-side pointer table would need a host-to-device copy per call, which
measures an order of magnitude more than the extra argument bindings.

Warm launches go through a pre-bound ``CompiledKernel`` obtained with
``JITFunction.run(..., warmup=True)``, so the per-call cost is one cache-key
build instead of the full binder + specialization + grid canonicalization
sequence.  Unaligned pointers and unknown keys fall back to ``kernel[grid]``.
"""

import torch
import triton
import triton.language as tl

try:  # pragma: no cover - availability probe
    from triton.runtime import driver as _triton_driver
except Exception:  # pragma: no cover
    _triton_driver = None

try:  # pragma: no cover - availability probe
    from triton import knobs as _triton_knobs
except Exception:  # pragma: no cover
    _triton_knobs = None

_MAX_TILE_BYTES = 32768
_MAX_TENSORS = 16

_TL_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
    torch.complex32: tl.float16,
    torch.complex64: tl.float32,
    torch.complex128: tl.float64,
}

_TORCH_NAME = {
    torch.float16: "Half",
    torch.bfloat16: "BFloat16",
    torch.float32: "Float",
    torch.float64: "Double",
    torch.int8: "Char",
    torch.int16: "Short",
    torch.int32: "Int",
    torch.int64: "Long",
    torch.uint8: "Byte",
    torch.bool: "Bool",
}


