@triton.jit
def _sqrt_tile(
    ptr,
    n,
    start,
    BLOCK: tl.constexpr,
    I64: tl.constexpr,
    IS_HALF: tl.constexpr,
    OUT_DT: tl.constexpr,
):
    if I64:
        offs = start + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offs = start + tl.arange(0, BLOCK)
    mask = offs < n
    x = tl.load(ptr + offs, mask=mask)
    if IS_HALF:
        # Native half sqrt: the backend evaluates it at full internal precision
        # (verified bitwise identical to ATen for fp16 and bf16) and it avoids
        # the fp32 widening buffer, which is what caps the tile size.
        y = tl.sqrt(x)
    else:
        y = tl.sqrt_rn(x)
    tl.store(ptr + offs, y, mask=mask)


@triton.jit(do_not_specialize=["n"])
def _sqrt_flat_kernel(
    x_ptr,
    n,
    BLOCK: tl.constexpr,
    I64: tl.constexpr,
    IS_HALF: tl.constexpr,
    OUT_DT: tl.constexpr,
):
    pid = tl.program_id(0)
    if I64:
        start = pid.to(tl.int64) * BLOCK
    else:
        start = pid * BLOCK
    _sqrt_tile(x_ptr, n, start, BLOCK, I64, IS_HALF, OUT_DT)


