@triton.jit(do_not_specialize=["n", "n_inner", "s_inner"])
def _sqrt_strided_kernel(
    x_ptr,
    n_inner,
    s_inner,
    meta_ptr,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
    IS_HALF: tl.constexpr,
    OUT_DT: tl.constexpr,
):
    """Row-per-program traversal of a collapsed strided view.

    ``meta_ptr`` holds ``RANK`` outer sizes followed by ``RANK`` outer strides
    (int64).  The outer row index is decomposed into coordinates with scalar
    div/mod only -- no per-element index math.
    """
    pi = tl.program_id(0)
    row = tl.program_id(1)

    base = row.to(tl.int64) * 0
    rem = row.to(tl.int64)
    for d in tl.static_range(RANK):
        sz = tl.load(meta_ptr + d)
        st = tl.load(meta_ptr + RANK + d)
        c = rem % sz
        rem = rem // sz
        base += c * st

    offs = pi.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < n_inner
    ptrs = x_ptr + base + offs * s_inner
    x = tl.load(ptrs, mask=mask)
    if IS_HALF:
        y = tl.sqrt(x)
    else:
        y = tl.sqrt_rn(x)
    tl.store(ptrs, y, mask=mask)


@triton.jit(do_not_specialize=["n"])
def _sqrt_complex_kernel(
    x_ptr,
    n,
    BLOCK: tl.constexpr,
    I64: tl.constexpr,
    R_DT: tl.constexpr,
):
    pid = tl.program_id(0)
    if I64:
        idx = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n
    rp = x_ptr + 2 * idx
    a = tl.load(rp, mask=mask)
    b = tl.load(rp + 1, mask=mask)
    m = tl.sqrt(a * a + b * b)
    r = tl.sqrt((m + a) * 0.5)
    i = tl.sqrt((m - a) * 0.5)
    i = tl.where(b < 0, -i, i)
    tl.store(rp, r.to(R_DT), mask=mask)
    tl.store(rp + 1, i.to(R_DT), mask=mask)


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------


def _pick_block(n, item_size=2):
    """Tile of at most ``_MAX_TILE_BYTES`` whose lane count is a power of two.

    A program pays a fixed synchronous-DMA wait plus vector barriers per tile
    iteration, so the number of bytes moved per iteration is what matters.
    A 32 KB tile was verified to compile and run for half dtypes with the
    native-precision sqrt used here.
    """
    cap = _MAX_TILE_BYTES // item_size
    if cap < 16:
        cap = 16
    if n >= cap:
        return cap
    b = 16
    while b < n:
        b <<= 1
    return b


def _collapse_dims(shape, stride):
    """Drop size-1 dims, sort by ascending stride and merge adjacent runs."""
    dims = sorted((int(sz), int(st)) for sz, st in zip(shape, stride) if sz != 1)
    if not dims:
        return [[1, 1]]
    merged = [[dims[0][0], dims[0][1]]]
    for sz, st in dims[1:]:
        psz, pst = merged[-1]
        if st == pst * psz:
            merged[-1][0] = psz * sz
        else:
            merged.append([sz, st])
    return merged


def _is_half(dt):
    return dt is torch.float16 or dt is torch.bfloat16


# ---------------------------------------------------------------------------
# warm-launch fast path
# ---------------------------------------------------------------------------

_FAST_FLAT = {}
_FAST_MULTI = {}


def _warm(jit_fn, cache, key, values, grid):
    """Compile (cache hit expected) without launching and memoize the handle."""
    entry = cache.get(key)
    if entry is not None:
        return entry
    if _triton_driver is None or getattr(jit_fn, "pre_run_hooks", None):
        return None
    try:
        kern = jit_fn.foreach_sqrt_(*values, grid=grid, warmup=True)
        entry = (kern, kern.foreach_sqrt_, kern.function, kern.packed_metadata)
    except Exception:
        return None
    cache[key] = entry
    return entry


def _fast_launch(entry, grid, values, dev):
    kern, launcher, function, packed = entry
    stream = _triton_driver.active.get_current_stream(dev)
    grid_0 = grid[0]
    size = len(grid)
    grid_1 = grid[1] if size > 1 else 1
    grid_2 = grid[2] if size > 2 else 1
    metadata = kern.launch_metadata(grid, stream, *values)
    if _triton_knobs is None:
        launcher(
            grid_0,
            grid_1,
            grid_2,
            stream,
            function,
            packed,
            metadata,
            None,
            None,
            *values,
        )
    else:
        runtime = _triton_knobs.runtime
        launcher(
            grid_0,
            grid_1,
            grid_2,
            stream,
            function,
            packed,
            metadata,
            runtime.launch_enter_hook,
            runtime.launch_exit_hook,
            *values,
        )


def _launch_flat(t, n):
    dt = t.dtype
    block = _pick_block(n, t.element_size())
    grid = ((n + block - 1) // block,)
    if dt.is_complex:
        _sqrt_complex_kernel[grid](t, n, block, n > 0x7FFFFFFF, _TL_DTYPE[dt])
        return
    i64 = n > 0x7FFFFFFF
    half = _is_half(dt)
    tdt = _TL_DTYPE[dt]
    dev = t.device.index or 0
    aligned = not (t.data_ptr() & 15)
    key = (dt, block, i64, half, dev)
    values = (t, n, block, i64, half, tdt)
    if aligned:
        entry = _FAST_FLAT.get(key)
        if entry is None:
            _sqrt_flat_kernel[grid](*values)
            _warm(_sqrt_flat_kernel, _FAST_FLAT, key, values, grid)
        else:
            _fast_launch(entry, grid, values, dev)
        return
    _sqrt_flat_kernel[grid](*values)


def _launch_multi(batch, dt):
    """One launch for 2.._MAX_TENSORS consecutive dense same-dtype tensors."""
    nt = len(batch)
    tensors = [e[0] for e in batch]
    numels = [e[3] for e in batch]
    mx = numels[0]
    aligned = True
    for e in batch:
        v = e[3]
        if v > mx:
            mx = v
        if e[2] & 15:
            aligned = False
    block = _pick_block(mx, dt.itemsize)
    pad = _MAX_TENSORS - nt
    if pad:
        tensors = tensors + [tensors[0]] * pad
        numels = numels + [0] * pad
    grid = (nt, (mx + block - 1) // block)
    i64 = mx > 0x7FFFFFFF
    half = _is_half(dt)
    tdt = _TL_DTYPE[dt]
    values = tuple(tensors) + tuple(numels) + (block, i64, half, tdt)
    if aligned:
        dev = batch[0][0].device.index or 0
        key = (dt, block, i64, half, dev)
        entry = _FAST_MULTI.get(key)
        if entry is None:
            _sqrt_multi_kernel[grid](*values)
            _warm(_sqrt_multi_kernel, _FAST_MULTI, key, values, grid)
        else:
            _fast_launch(entry, grid, values, dev)
        return
    _sqrt_multi_kernel[grid](*values)


def _launch_strided(t, dims):
    dt = t.dtype
    inner_sz, inner_st = dims[0]
    outer = dims[1:]
    n_outer = 1
    for sz, _st in outer:
        n_outer *= sz
    block = _pick_block(inner_sz, t.element_size())
    meta = torch.tensor(
        [d[0] for d in outer] + [d[1] for d in outer],
        dtype=torch.int64,
        device=t.device,
    )
    grid = ((inner_sz + block - 1) // block, n_outer)
    _sqrt_strided_kernel[grid](
        t,
        inner_sz,
        inner_st,
        meta,
        len(outer),
        block,
        _is_half(dt),
        _TL_DTYPE[dt],
    )


def _as_tensor_list(obj):
    if isinstance(obj, torch.Tensor):
        return [obj]
    if isinstance(obj, (list, tuple)):
        return list(obj)
    return list(obj)


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------


def foreach_sqrt_(*args, **kwargs):
    if "self" in kwargs:
        seq = kwargs.pop("self")
        tensors = _as_tensor_list(seq) + list(args)
    elif len(args) == 1:
        tensors = _as_tensor_list(args[0])
    else:
        tensors = list(args)

    if not isinstance(tensors, list):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")

    # single pass: validate like ATen and build the launch plan
    plan = []
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        dt = t.dtype
        if dt.is_complex:
            if dt is not torch.complex64 and dt is not torch.complex128:
                raise RuntimeError(
                    '"foreach" not implemented for \''
                    + str(dt).replace("torch.", "")
                    + "'"
                )
        elif not dt.is_floating_point:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                + _TORCH_NAME.get(dt, str(dt).replace("torch.", "").capitalize())
            )
        n = t.numel()
        if n == 0:
            continue
        dims = None
        if n > 1 and not t.is_contiguous():
            for sz, st in zip(t.shape, t.stride()):
                if sz > 1 and st == 0:
                    raise RuntimeError(
                        "unsupported operation: more than one element of the "
                        "written-to tensor refers to a single memory location. "
                        "Please clone() the tensor before performing the "
                        "operation."
                    )
            collapsed = _collapse_dims(t.shape, t.stride())
            if len(collapsed) == 1 and collapsed[0][1] == 1:
                dims = None
            else:
                dims = collapsed
        plan.append((t, dims, t.data_ptr(), n))

    i = 0
    total = len(plan)
    while i < total:
        t, dims, ptr, n = plan[i]
        if dims is not None:
            _launch_strided(t, dims)
            i += 1
            continue
        dt = t.dtype
        if dt.is_complex:
            _launch_flat(t, n)
            i += 1
            continue
        batch = [plan[i]]
        seen = {ptr}
        j = i + 1
        while j < total and len(batch) < _MAX_TENSORS:
            u = plan[j]
            if u[1] is not None or u[0].dtype is not dt:
                break
            uptr = u[2]
            if uptr in seen:
                break
            seen.add(uptr)
            batch.append(u)
            j += 1
        if len(batch) == 1:
            _launch_flat(t, n)
        else:
            _launch_multi(batch, dt)
        i = j

    return None
